-- ─── 2) Grants ────────────────────────────────────────────────────
--
-- Least privilege. The outbox and the settings row are never deleted by the
-- application (a tenant purge cascades, as the table owner); the bell's rows
-- may be. The REVOKE is explicit because a database's default privileges
-- (prisma/init-roles.sh) may already have granted more.
GRANT SELECT, INSERT, UPDATE ON "NotificationOutbox", "TenantNotificationSettings" TO app_user;
REVOKE DELETE, TRUNCATE ON "NotificationOutbox", "TenantNotificationSettings" FROM app_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON "Notification" TO app_user;

-- ─── 3) Canonical RLS on the direct tenant tables ─────────────────
--
-- The shape of docs/rls-tenant-isolation.md, "Adding a new tenant-scoped
-- table". `Notification` is per-user as well, but the user predicate lives in
-- `NotificationRepository` (an RLS user predicate would need an
-- `app.user_id` setting, which nothing sets; see docs/rls-tenant-isolation.md).

ALTER TABLE "Notification" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Notification" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "Notification"
    USING ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY tenant_isolation_insert ON "Notification"
    FOR INSERT WITH CHECK ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY superuser_bypass ON "Notification"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "NotificationOutbox" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "NotificationOutbox" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "NotificationOutbox"
    USING ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY tenant_isolation_insert ON "NotificationOutbox"
    FOR INSERT WITH CHECK ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY superuser_bypass ON "NotificationOutbox"
    USING (current_setting('role') != 'app_user');

ALTER TABLE "TenantNotificationSettings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TenantNotificationSettings" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "TenantNotificationSettings"
    USING ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY tenant_isolation_insert ON "TenantNotificationSettings"
    FOR INSERT WITH CHECK ("tenantId" = current_setting('app.tenant_id', true)::text);
CREATE POLICY superuser_bypass ON "TenantNotificationSettings"
    USING (current_setting('role') != 'app_user');

-- ─── 4) The per-workspace SYSTEM user ─────────────────────────────
--
-- A background job that must write a NOT NULL foreign key to `User` (a work
-- item's creator, 2.1) writes it as the workspace's system user instead of
-- borrowing a real member. The row is created lazily by
-- `ensureTenantSystemUser` (src/app-layer/context-system.ts). Its shape is
-- fixed by its id:
--
--   id           'sys_' || <tenantId>      (a cuid never contains '_')
--   emailHash    'system:' || <tenantId>   (never a 64-hex HMAC, so no
--                                           lookup by email can reach it)
--   passwordHash NULL
--
-- The constraints below make that shape, and the row's inability to sign in
-- or hold standing anywhere, a property of the DATABASE rather than of each
-- code path that might otherwise find it.

-- Preflight: nothing may already occupy the reserved namespace. Ids are
-- cuids and hashes are hex, so this refuses only a database somebody edited
-- by hand.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM "User"
        WHERE id LIKE 'sys\_%' OR "emailHash" LIKE 'system:%'
    ) THEN
        RAISE EXCEPTION 'User rows already occupy the reserved system namespace (id sys_* or emailHash system:*)';
    END IF;
END $$;

-- The row's shape: a 'sys_' id and a 'system:' hash come together or not at
-- all, the hash names the same workspace as the id, and a system row never
-- has a password. A rewrite of the row's email re-hashes it (the PII
-- extension derives `emailHash` on every write that carries an email), which
-- breaks the second clause, so the row cannot be repointed at a real address.
ALTER TABLE "User" ADD CONSTRAINT "User_system_row_shape" CHECK (
    (id LIKE 'sys\_%') = ("emailHash" LIKE 'system:%')
    AND (
        id NOT LIKE 'sys\_%'
        OR ("emailHash" = 'system:' || substr(id, 5) AND "passwordHash" IS NULL)
    )
);

-- Never a sign-in, a membership, a credential or a session. Every path to a
-- session or a context needs a row in one of these tables (or a password,
-- refused above), so refusing the system id here closes all of them at once.
-- A table created later that can carry a user's standing (UserIdentityLink in
-- 8.3, TenantApiKey in 5.2) gets the same CHECK in the migration that creates
-- it.
ALTER TABLE "Account"            ADD CONSTRAINT "Account_not_system_user"            CHECK ("userId" NOT LIKE 'sys\_%');
ALTER TABLE "TenantMembership"   ADD CONSTRAINT "TenantMembership_not_system_user"   CHECK ("userId" NOT LIKE 'sys\_%');
ALTER TABLE "OrgMembership"      ADD CONSTRAINT "OrgMembership_not_system_user"      CHECK ("userId" NOT LIKE 'sys\_%');
ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_not_system_user" CHECK ("userId" NOT LIKE 'sys\_%');
ALTER TABLE "UserMfaEnrollment"  ADD CONSTRAINT "UserMfaEnrollment_not_system_user"  CHECK ("userId" NOT LIKE 'sys\_%');
ALTER TABLE "UserSession"        ADD CONSTRAINT "UserSession_not_system_user"        CHECK ("userId" NOT LIKE 'sys\_%');
